/**
 * การค้นหาที่มีความแม่นยำสูงและ Semantic Query Engine
 */
ส่งออกฟังก์ชัน async searchSentences (
  แบบสอบถาม:สตริง
  ตัวกรอง: SearchFilterOptions = {}
): สัญญา<{ ผลลัพธ์: SentenceItem[]; รวม:หมายเลข; semanticMatches?: SemanticExplanationMatch[] }> {
  const all = รอโหลดSentences();
  const NormalizedQuery = NormalizeText (แบบสอบถาม);
  const queryTokens = แบบสอบถามปกติ ? NormalizedQuery.split(' ').filter(บูลีน) : [];

  const {
    ซีฟร์ = 'ทั้งหมด',
    ส่วน = 'ทั้งหมด',
    หมวดหมู่ = 'ทั้งหมด',
    หมวดหมู่ย่อย = 'ทั้งหมด',
    ไวยากรณ์ = 'ทั้งหมด',
    พิธีการ = 'ทั้งหมด',
    ขีดจำกัด = 50,
    ออฟเซ็ต = 0,
  } = ตัวกรอง;

  // กรองผ่าน
  ให้กรอง = all.filter(s => {
    ถ้า (cefr !== 'ทั้งหมด' && s.cefr !== cefr) กลับเท็จ;
    ถ้า (ส่วน !== 'ทั้งหมด' && s.section !==section) กลับเท็จ;
    ถ้า (หมวดหมู่ !== 'ทั้งหมด' && s.category !== หมวดหมู่) กลับเท็จ;
    ถ้า (หมวดหมู่ย่อย !== 'ทั้งหมด' && s.subcategory !== หมวดหมู่ย่อย) กลับเท็จ;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) กลับเท็จ;
    if (formality !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) กลับเท็จ;
    กลับเป็นจริง;
  });

  ถ้า (!normalizedQuery) {
    const รวม = filtered.length;
    const paginated = กรองแล้ว ชิ้น (ออฟเซ็ต, ออฟเซ็ต + ขีด จำกัด );
    กลับ { ผลลัพธ์: แบ่งหน้า, รวม };
  }

  // อัลกอริทึมการให้คะแนน
  อินเทอร์เฟซ ScoredItem {
    รายการ: SentenceItem;
    คะแนน:หมายเลข;
    ด้าน: SemanticExplanationMatch ['matchedAspect'];
  }

  คะแนน const: ScoredItem[] = [];

  สำหรับ (const s ของตัวกรอง) {
    ให้คะแนน = 0;
    ให้matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'english';

    const normEn = NormalizeText (s.english);
    const normEg = ทำให้เป็นมาตรฐาน (s.arabicEg);
    const normFusha = ทำให้ข้อความเป็นมาตรฐาน (s.arabicFusha);
    const normGrammar = ทำให้ข้อความปกติ (s.grammar);
    const normPurpose = NormalizeText (s.Purpose);

    // ตรงทุกประการของประโยคเต็ม
    ถ้า (normEn === NormalizedQuery) {
      คะแนน += 100;
      matchedAspect = 'ภาษาอังกฤษ';
    } อื่น ๆ ถ้า (normEg === NormalizedQuery) {
      คะแนน += 95;
      matchedAspect = 'ภาษาอาหรับ-เช่น';
    } อื่น ๆ ถ้า (normFusha === NormalizedQuery) {
      คะแนน += 90;
      matchedAspect = 'อารบิก-ฟูชา';
    }

    //สตริงย่อยประกอบด้วย
    ถ้า (normEn.includes (normalizedQuery)) {
      คะแนน += 50;
      matchedAspect = 'ภาษาอังกฤษ';
    } อื่น ๆ ถ้า (normEg.includes (normalizedQuery)) {
      คะแนน += 45;
      matchedAspect = 'ภาษาอาหรับ-เช่น';
    } อื่นถ้า (normFusha.includes (normalizedQuery)) {
      คะแนน += 40;
      matchedAspect = 'อารบิก-ฟูชา';
    } อื่น ๆ ถ้า (normGrammar.includes (normalizedQuery)) {
      คะแนน += 35;
      matchedAspect = 'ไวยากรณ์';
    } อื่น ๆ ถ้า (normPurpose.includes (normalizedQuery)) {
      คะแนน += 30;
      matchedAspect = 'แนวคิด';
    }

    // การจับคู่โทเค็น
    ให้ tokenMatches = 0;
    สำหรับ (โทเค็น const ของ queryTokens) {
      ถ้า (normEn.includes (โทเค็น)) tokenMatches += 5;
      ถ้า (normEg.includes (โทเค็น)) tokenMatches += 4;
      ถ้า (normFusha.includes (โทเค็น)) tokenMatches += 3;
      ถ้า (s.vocabulary.some(v => NormalizeText(v).includes(token))) tokenMatches += 4;
      ถ้า (s.tags.some(t => NormalizeText(t).includes(token))) tokenMatches += 3;
    }
    คะแนน += tokenMatches;

    ถ้า (คะแนน > 0) {
      Score.push({ item: s, คะแนน, ลักษณะ: matchedAspect });
    }
  }

  Score.sort((a, b) => b.score - a.score);

  // คำอธิบายความหมายตรงกับรายการยอดนิยม
  const semanticMatches: SemanticExplanationMatch[] = Score.slice(0, 5).map(s => {
    ให้แตกต่างกันนิดหน่อย = '';
    ถ้า (s.item.grammar.toLowerCase().includes('อดีตต่อเนื่อง')) {
      nuance = 'อดีตกาลต่อเนื่องแสดงให้เห็นว่าเหตุการณ์กำลังดำเนินอยู่ ณ จุดใดจุดหนึ่งในอดีต';
    } อื่น ๆ ถ้า (s.item.grammar.toLowerCase().includes('present perfect integrated')) {
      nuance = 'กาลต่อเนื่องที่สมบูรณ์แบบในปัจจุบันเน้นเวลาจากอดีตและต่อเนื่องไปจนถึงช่วงเวลาที่พูด';
    } อื่น ๆ ถ้า (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuance = 'อนาคตกาลที่สมบูรณ์แบบเป็นการแสดงออกถึงเหตุการณ์ที่จะแล้วเสร็จก่อนเวลาที่กำหนดในอนาคต';
    } อื่น ๆ ถ้า (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'รูปแบบของการร้องขอทางอ้อมคือจุดสุดยอดของมารยาททางการฑูตในการสื่อสารภาษาอังกฤษ';
    }
    กลับ {
      ประโยค: s.item,
      ความคล้ายคลึงกันคะแนน: Math.min(100, s.score)
      แตกต่างกันนิดหน่อยExplanationAr: แตกต่างกันนิดหน่อย,
      matchedAspect: s.spect,
    };
  });

  คะแนนรวม = คะแนน ความยาว;
  const paginated = Score.slice (ออฟเซ็ต, ออฟเซ็ต + ขีด จำกัด ). map (s => s.item);

  กลับ {
    ผลลัพธ์: แบ่งหน้า,
    รวม,
    การจับคู่ความหมาย,
  };
}

/**
